function parseMD(md) {
  const lines = md.split("\n"), result = [];
  let inCode=false, lang="", codeLines=[], inTable=false, tableRows=[];
  const flushTable=()=>{ if(tableRows.length){result.push({type:"table",rows:tableRows});tableRows=[];inTable=false;}};
  for(let i=0;i<lines.length;i++){
    const L=lines[i];
    if(L.startsWith("```")){
      if(!inCode){flushTable();inCode=true;lang=L.slice(3).trim();codeLines=[];}
      else{result.push({type:"code",lang,content:codeLines.join("\n")});inCode=false;codeLines=[];lang="";}
      continue;
    }
    if(inCode){codeLines.push(L);continue;}
    if(L.startsWith("|")){
      if(L.match(/^\|[\s\-|]+\|$/))continue;
      const cells=L.split("|").filter((_,i,a)=>i>0&&i<a.length-1).map(c=>c.trim());
      if(!inTable){inTable=true;tableRows=[{header:true,cells}];}else tableRows.push({header:false,cells});
      continue;
    }else if(inTable)flushTable();
    if(L.startsWith("# "))     {result.push({type:"h1",c:L.slice(2)});continue;}
    if(L.startsWith("## "))    {result.push({type:"h2",c:L.slice(3)});continue;}
    if(L.startsWith("### "))   {result.push({type:"h3",c:L.slice(4)});continue;}
    if(L.startsWith("#### "))  {result.push({type:"h4",c:L.slice(5)});continue;}
    if(L.startsWith("> "))     {result.push({type:"bq",c:L.slice(2)});continue;}
    if(L.startsWith("- ")||L.startsWith("* ")){result.push({type:"li",c:L.slice(2)});continue;}
    if(L.match(/^\d+\. /))     {result.push({type:"oli",c:L.replace(/^\d+\. /,"")});continue;}
    if(L.startsWith("---"))    {result.push({type:"hr"});continue;}
    if(L.trim()==="")          {result.push({type:"br"});continue;}
    result.push({type:"p",c:L});
  }
  flushTable();
  return result;
}

function fmt(t){
  if(!t)return t;
  return t
    .replace(/`([^`]+)`/g,'<code style="background:#1e293b;color:#7dd3fc;padding:1px 5px;border-radius:3px;font-size:.83em;font-family:monospace">$1</code>')
    .replace(/\*\*([^*]+)\*\*/g,'<strong style="color:#f1f5f9">$1</strong>')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2" style="color:#60a5fa;text-decoration:underline" target="_blank">$1</a>');
}

function MD({ content }) {
  const tokens=parseMD(content);
  let liB=[],oliB=[];
  const els=[];
  const fLi=()=>{if(liB.length){els.push(<ul key={`u${els.length}`} style={{margin:"5px 0 5px 18px",paddingLeft:0}}>{liB.map((x,j)=><li key={j} style={{color:"#cbd5e1",marginBottom:3,lineHeight:1.7,fontSize:".93em"}} dangerouslySetInnerHTML={{__html:fmt(x)}}/>)}</ul>);liB=[];}};
  const fOli=()=>{if(oliB.length){els.push(<ol key={`o${els.length}`} style={{margin:"5px 0 5px 18px",paddingLeft:14}}>{oliB.map((x,j)=><li key={j} style={{color:"#cbd5e1",marginBottom:3,lineHeight:1.7,fontSize:".93em"}} dangerouslySetInnerHTML={{__html:fmt(x)}}/>)}</ol>);oliB=[];}};
  tokens.forEach((tok,idx)=>{
    if(tok.type!=="li")fLi();
    if(tok.type!=="oli")fOli();
    switch(tok.type){
      case"h1":els.push(<h1 key={idx} style={{fontSize:"1.45em",fontWeight:800,color:"#f1f5f9",borderBottom:"2px solid #334155",paddingBottom:7,margin:"22px 0 12px"}} dangerouslySetInnerHTML={{__html:fmt(tok.c)}}/>);break;
      case"h2":els.push(<h2 key={idx} style={{fontSize:"1.08em",fontWeight:700,color:"#e2e8f0",margin:"18px 0 8px",paddingLeft:9,borderLeft:"3px solid #3b82f6"}} dangerouslySetInnerHTML={{__html:fmt(tok.c)}}/>);break;
      case"h3":els.push(<h3 key={idx} style={{fontSize:".92em",fontWeight:700,color:"#94a3b8",margin:"14px 0 5px"}} dangerouslySetInnerHTML={{__html:fmt(tok.c)}}/>);break;
      case"h4":els.push(<div key={idx} style={{background:"#0d1f2d",border:"1px solid #1e3a4a",borderLeft:"3px solid #0ea5e9",borderRadius:"0 6px 6px 0",padding:"9px 13px",margin:"12px 0 6px"}}><span style={{fontSize:".8em",fontWeight:700,color:"#38bdf8"}} dangerouslySetInnerHTML={{__html:"💡 "+fmt(tok.c)}}/></div>);break;
      case"bq":if(tok.c.trim())els.push(<blockquote key={idx} style={{borderLeft:"3px solid #f59e0b",background:"#1c1a10",margin:"8px 0",padding:"9px 14px",color:"#fcd34d",borderRadius:"0 6px 6px 0",fontStyle:"italic",fontSize:".93em"}} dangerouslySetInnerHTML={{__html:fmt(tok.c)}}/>);break;
      case"code":els.push(<pre key={idx} style={{background:"#0f172a",border:"1px solid #1e293b",borderRadius:7,padding:"13px 15px",overflowX:"auto",margin:"10px 0",fontSize:".79em",lineHeight:1.7}}><code style={{color:"#e2e8f0",fontFamily:"'JetBrains Mono','Fira Code',monospace"}}>{tok.content}</code></pre>);break;
      case"table":els.push(<div key={idx} style={{overflowX:"auto",margin:"9px 0"}}><table style={{borderCollapse:"collapse",width:"100%",fontSize:".83em"}}><tbody>{tok.rows.map((row,ri)=><tr key={ri} style={{background:row.header?"#1e293b":ri%2===0?"#0f172a":"#111827"}}>{row.cells.map((cell,ci)=><td key={ci} style={{padding:"7px 11px",border:"1px solid #1e293b",color:row.header?"#94a3b8":"#cbd5e1",fontWeight:row.header?600:400}} dangerouslySetInnerHTML={{__html:fmt(cell)}}/>)}</tr>)}</tbody></table></div>);break;
      case"li":liB.push(tok.c);break;
      case"oli":oliB.push(tok.c);break;
      case"hr":els.push(<hr key={idx} style={{border:"none",borderTop:"1px solid #1e293b",margin:"16px 0"}}/>);break;
      case"br":break;
      case"p":els.push(<p key={idx} style={{color:tok.c.startsWith("→")?"#64748b":"#cbd5e1",lineHeight:1.75,margin:"4px 0",fontSize:".93em"}} dangerouslySetInnerHTML={{__html:fmt(tok.c)}}/>);break;
    }
  });
  fLi();fOli();
  return <div>{els}</div>;
}

function StoryMap({ onSelect }) {
  return (
    <div style={{padding:"28px 32px 48px",maxWidth:860,margin:"0 auto"}}>
      <div style={{marginBottom:28}}>
        <div style={{fontSize:".7em",fontWeight:700,color:"#475569",letterSpacing:".1em",textTransform:"uppercase",marginBottom:4}}>HanaMall インフラチーム</div>
        <h1 style={{fontSize:"1.6em",fontWeight:800,color:"#f1f5f9",margin:"0 0 6px"}}>田中さんの12週間</h1>
        <p style={{color:"#64748b",fontSize:".88em",margin:0}}>ECサイト「HanaMall」に中途入社した田中さんのストーリー。先輩・佐藤さんからのSlack指示をこなしながら実務スキルを身につける。</p>
      </div>
      {[1,2,3,4].map(phase=>{
        const pc=PC[phase];
        return (
          <div key={phase} style={{marginBottom:28}}>
            <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}>
              <span style={{background:pc.bg,color:pc.badge,border:`1px solid ${pc.border}`,fontSize:".7em",fontWeight:700,padding:"3px 10px",borderRadius:4,textTransform:"uppercase",letterSpacing:".06em"}}>{pc.label}</span>
              <div style={{flex:1,height:1,background:"#1e293b"}}/>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(190px,1fr))",gap:10}}>
              {WEEKS.filter(w=>w.phase===phase).map(w=>(
                <button key={w.key} onClick={()=>onSelect(w.key)}
                  style={{background:"#0a0f1e",border:`1px solid ${pc.border}`,borderRadius:8,padding:"12px 14px",textAlign:"left",cursor:"pointer",transition:"transform .15s"}}
                  onMouseEnter={e=>e.currentTarget.style.transform="translateY(-2px)"}
                  onMouseLeave={e=>e.currentTarget.style.transform="translateY(0)"}>
                  <div style={{fontSize:".7em",fontWeight:700,color:pc.badge,marginBottom:4}}>{w.label}</div>
                  <div style={{fontSize:".8em",fontWeight:700,color:"#e2e8f0",marginBottom:6,lineHeight:1.3}}>{w.title}</div>
                  <div style={{fontSize:".72em",color:"#64748b",lineHeight:1.4,borderTop:"1px solid #1e293b",paddingTop:6}}>💬 {w.slack}</div>
                </button>
              ))}
            </div>
          </div>
        );
      })}
      <div style={{marginTop:32,background:"#0a0f1e",border:"1px solid #1e293b",borderRadius:10,padding:"16px 20px"}}>
        <div style={{fontSize:".75em",fontWeight:700,color:"#475569",marginBottom:10,textTransform:"uppercase",letterSpacing:".08em"}}>登場人物</div>
        <div style={{display:"flex",gap:24,flexWrap:"wrap"}}>
          {[{icon:"👤",name:"田中（あなた）",desc:"中途入社1ヶ月目\nインフラエンジニア",color:"#0ea5e9"},
            {icon:"👨‍💻",name:"佐藤（先輩）",desc:"インフラチームリーダー\n各Weekの指示を出す人",color:"#40916c"},
            {icon:"🛒",name:"HanaMall",desc:"架空のECサイト\nインフラを守る対象",color:"#9333ea"}].map(p=>(
            <div key={p.name} style={{display:"flex",gap:10,alignItems:"flex-start"}}>
              <div style={{width:36,height:36,borderRadius:"50%",background:"#0f172a",border:`2px solid ${p.color}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:"1.1em",flexShrink:0}}>{p.icon}</div>
              <div>
                <div style={{fontSize:".82em",fontWeight:700,color:"#f1f5f9"}}>{p.name}</div>
                <div style={{fontSize:".75em",color:"#64748b",whiteSpace:"pre-line"}}>{p.desc}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const [selected, setSelected] = useState("STORY");
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const current = WEEKS.find(w=>w.key===selected);
  const grouped = [null,1,2,3,4].map(phase=>({phase,items:phase===null?WEEKS.filter(w=>!w.phase):WEEKS.filter(w=>w.phase===phase)}));
  const ALL = ["STORY",...WEEKS.map(w=>w.key)];
  const ci = ALL.indexOf(selected);
  const prevKey = ci>0?ALL[ci-1]:null;
  const nextKey = ci<ALL.length-1?ALL[ci+1]:null;
  const pLabel = prevKey==="STORY"?"🗺 ストーリー":WEEKS.find(w=>w.key===prevKey)?.label;
  const nLabel = nextKey==="STORY"?"🗺 ストーリー":WEEKS.find(w=>w.key===nextKey)?.label;

  return (
    <div style={{display:"flex",height:"100vh",background:"#020617",fontFamily:"'Noto Sans JP','Inter',sans-serif",color:"#e2e8f0"}}>
      <div style={{width:sidebarOpen?256:0,minWidth:sidebarOpen?256:0,background:"#0a0f1e",borderRight:"1px solid #1e293b",overflow:"hidden",transition:"width .2s,min-width .2s",display:"flex",flexDirection:"column"}}>
        <div style={{padding:"14px 12px 8px",borderBottom:"1px solid #1e293b",flexShrink:0}}>
          <div style={{fontSize:".66em",fontWeight:700,color:"#475569",letterSpacing:".1em",textTransform:"uppercase",marginBottom:2}}>HanaMall インフラ</div>
          <div style={{fontSize:".95em",fontWeight:800,color:"#f1f5f9"}}>Linux実務習得</div>
        </div>
        <div style={{overflowY:"auto",flex:1,padding:"6px 0"}}>
          <button onClick={()=>setSelected("STORY")} style={{display:"block",width:"100%",textAlign:"left",background:selected==="STORY"?"#0f172a":"transparent",border:"none",borderLeft:selected==="STORY"?"3px solid #f59e0b":"3px solid transparent",padding:"8px 14px 8px 12px",cursor:"pointer"}}>
            <div style={{fontSize:".78em",fontWeight:700,color:selected==="STORY"?"#f1f5f9":"#64748b"}}>🗺 ストーリーマップ</div>
          </button>
          {grouped.map(({phase,items})=>(
            <div key={phase??"r"}>
              {phase&&<div style={{padding:"10px 14px 3px",fontSize:".64em",fontWeight:700,color:PC[phase].badge,letterSpacing:".08em",textTransform:"uppercase"}}>{PC[phase].label}</div>}
              {items.map(w=>(
                <button key={w.key} onClick={()=>setSelected(w.key)} style={{display:"block",width:"100%",textAlign:"left",background:selected===w.key?(phase?PC[phase].bg:"#0f172a"):"transparent",border:"none",borderLeft:selected===w.key?`3px solid ${phase?PC[phase].badge:"#3b82f6"}`:"3px solid transparent",padding:"6px 14px 6px 12px",cursor:"pointer"}}>
                  <div style={{fontSize:".77em",fontWeight:700,color:selected===w.key?"#f1f5f9":"#64748b"}}>{w.label}</div>
                  {w.title&&<div style={{fontSize:".68em",color:selected===w.key?(phase?PC[phase].text:"#94a3b8"):"#334155",marginTop:1,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{w.title}</div>}
                </button>
              ))}
            </div>
          ))}
        </div>
      </div>
      <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden"}}>
        <div style={{height:44,background:"#0a0f1e",borderBottom:"1px solid #1e293b",display:"flex",alignItems:"center",padding:"0 16px",gap:12,flexShrink:0}}>
          <button onClick={()=>setSidebarOpen(v=>!v)} style={{background:"none",border:"none",color:"#64748b",cursor:"pointer",fontSize:"1.1em",padding:"4px 6px"}}>☰</button>
          {selected==="STORY"
            ?<span style={{fontSize:".84em",fontWeight:600,color:"#f59e0b"}}>🗺 ストーリーマップ</span>
            :<>
              {current?.phase&&<span style={{fontSize:".68em",fontWeight:700,background:PC[current.phase].bg,color:PC[current.phase].badge,border:`1px solid ${PC[current.phase].border}`,padding:"2px 8px",borderRadius:4}}>{PC[current.phase].label}</span>}
              <span style={{fontSize:".84em",fontWeight:600,color:"#94a3b8"}}>{current?.label}{current?.title?` — ${current.title}`:""}</span>
            </>
          }
        </div>
        <div style={{flex:1,overflowY:"auto"}}>
          {selected==="STORY"
            ?<StoryMap onSelect={setSelected}/>
            :<div style={{padding:"22px 30px 48px"}}><div style={{maxWidth:820,margin:"0 auto"}}><MD content={README_DATA[selected]||""}/></div></div>
          }
        </div>
        <div style={{height:46,background:"#0a0f1e",borderTop:"1px solid #1e293b",display:"flex",alignItems:"center",justifyContent:"space-between",padding:"0 22px",flexShrink:0}}>
          <button onClick={()=>prevKey&&setSelected(prevKey)} disabled={!prevKey} style={{background:"none",border:"1px solid #1e293b",color:prevKey?"#94a3b8":"#1e293b",padding:"4px 13px",borderRadius:5,cursor:prevKey?"pointer":"default",fontSize:".78em"}}>← {pLabel??""}</button>
          <span style={{fontSize:".7em",color:"#334155"}}>{ci+1} / {ALL.length}</span>
          <button onClick={()=>nextKey&&setSelected(nextKey)} disabled={!nextKey} style={{background:"none",border:"1px solid #1e293b",color:nextKey?"#94a3b8":"#1e293b",padding:"4px 13px",borderRadius:5,cursor:nextKey?"pointer":"default",fontSize:".78em"}}>{nLabel??""} →</button>
        </div>
      </div>
    </div>
  );
}
